%% 五种算法最终均针对第六组实验数据进行对比

tic
[f1,r_load1,V_bias1,R_load1] = IEEE123function1_plus(vals);
[f2,r_load2,V_bias2,R_load2] = IEEE123function2_plus(vals);
[f3,r_load3,V_bias3,R_load3] = IEEE123function3_plus(vals);
[f4,r_load4,V_bias4,R_load4] = IEEE123function4_plus(vals);
[f5,r_load5,V_bias5,R_load5] = IEEE123function5_plus(vals);
[f6,r_load6,V_bias6,R_load6] = IEEE123function6_plus(vals);
[f7,r_load7,V_bias7,R_load7] = IEEE123function7_plus(vals);
[f8,r_load8,V_bias8,R_load8] = IEEE123function8_plus(vals);
[f9,r_load9,V_bias9,R_load9] = IEEE123function9_plus(vals);
toc

% 归一化的方法
Ees_cost = 105; % 电池配置价格 单位:万美元/10MWh
w_ess = 0.003; % 储能成本权重-每年可能发生的 1-2 次 电网断电事故;储能预期使用年限：10 – 15 年

ob1 = 0.1*(1/2*(f1+f2) + (0.699*f3+0.190 *f4+0.111*f5)); %由于成本系数单位为万美元/10MWh 但实验的功率基准值为1MWh 所以计算成本时要乘以0.1
ob2 = 0.1*(0.4430*f6+0.2740*f7+0.2450*f8+0.0380*f9);
X   = 0.1*(w_ess*Ees_cost*sum(vals));
objective(i,:) = ob1 + ob2 + X;

% r_load = (r_load1+r_load2+r_load3+r_load4+r_load5)/5;
% V_bias = (V_bias1+V_bias2+V_bias3+V_bias4+V_bias5)/5;
% r_load = (r_load6+r_load7+r_load8+r_load9)/4;
% V_bias = (V_bias6+V_bias7+V_bias8+V_bias9)/4;
r_load = (r_load1+r_load2+r_load3+r_load4+r_load5+r_load6+r_load7+r_load8+r_load9)/9;
V_bias = (V_bias1+V_bias2+V_bias3+V_bias4+V_bias5+V_bias6+V_bias7+V_bias8+V_bias9)/9;
R_load = (R_load1+R_load2+R_load3+R_load4+R_load5+R_load6+R_load7+R_load8+R_load9)/9;
R_load = R_load';
V_bias = sum(V_bias)/4;
r_load = value(r_load);
V_bias = value(V_bias);
end




